<script lang="ts">import DashboardContent from '$lib/components/DashboardContent.svelte';import{Button}from'$lib/components/ui/button/index.js';import{Plus}from'lucide-svelte';import{enhance}from'$app/forms';import{dispatchToast}from'$lib/notifications';const{data}= $props();let open=$state(false);let submitting=$state(false);const enrollments=$derived(data.enrollments);function submit(){submitting=true;return async({result,update}:any)=>{if(result.type==='success'){open=false;dispatchToast('Saved',result.data?.message??'Saved')}else if(result.type==='failure')dispatchToast('Error',result.data?.message??'Could not enroll');await update();submitting=false;}}</script>
<DashboardContent title="Enrollment" subtitle="Assign students to a class for an academic year without overwriting history">{#snippet headerActions()}<Button size="sm" onclick={()=>open=true}><Plus class="h-3.5 w-3.5"/> Enroll Student</Button>{/snippet}<div class="overflow-hidden rounded-xl border border-border bg-white"><div class="grid grid-cols-[1.5fr_1fr_1.4fr_1fr] gap-3 border-b bg-muted/40 px-4 py-3 text-xs font-semibold text-muted-foreground"><span>Student</span><span>Academic Year</span><span>Class / Stream</span><span>Status</span></div>{#each enrollments as e}<div class="grid grid-cols-[1.5fr_1fr_1.4fr_1fr] gap-3 border-b px-4 py-3 last:border-0"><div><p class="text-sm font-medium">{e.students?.first_name} {e.students?.last_name}</p><p class="text-[11px] text-muted-foreground">{e.students?.admission_no}</p></div><span class="text-sm">{e.academic_year}</span><span class="text-sm">{e.sis_classes?.name??'—'} {e.sis_classes?.stream?`· ${e.sis_classes.stream}`:''}</span><span class="capitalize text-sm">{e.status}</span></div>{:else}<div class="px-6 py-12 text-center text-sm text-muted-foreground">No enrollments recorded yet.</div>{/each}</div></DashboardContent>
{#if open}<div class="fixed inset-0 z-50 flex items-center justify-center bg-black/30 p-4"><div class="w-full max-w-lg rounded-2xl bg-white shadow-xl"><div class="border-b px-6 py-4"><h2 class="font-semibold">Enroll Student</h2><p class="text-xs text-muted-foreground">Creates a historical enrollment record.</p></div><form method="POST" action="?/create" use:enhance={submit} class="grid gap-4 px-6 py-5"><label class="field-label">Student<select name="student_id" required class="field"><option value="">Select student</option>{#each data.students as s}<option value={s.id}>{s.admission_no} — {s.first_name} {s.last_name}</option>{/each}</select></label><label class="field-label">Academic Year<input name="academic_year" list="years" required class="field" placeholder="2027"/></label><datalist id="years">{#each data.classes as c}{#if c.academic_year}<option value={c.academic_year}/>{/if}{/each}</datalist><label class="field-label">Class / Stream<select name="class_id" required class="field"><option value="">Select class</option>{#each data.classes as c}<option value={c.id}>{c.name}{c.stream?` · ${c.stream}`:''} · {c.academic_year??'Any year'}</option>{/each}</select></label><label class="field-label">Enrollment Date<input name="enrolled_on" type="date" required class="field" value={new Date().toISOString().slice(0,10)}/></label><div class="flex justify-end gap-2"><Button type="button" variant="outline" onclick={()=>open=false}>Cancel</Button><Button type="submit" disabled={submitting}>{submitting?'Saving…':'Enroll'}</Button></div></form></div></div>{/if}<style>.field-label{font-size:.75rem;font-weight:600}.field{width:100%;display:block;margin-top:.3rem;border:1px solid hsl(var(--border));border-radius:.5rem;padding:.55rem .7rem;font-size:.875rem;outline:none}</style>
